import { createDashboard } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    Create_dash_board: Boolean
  },
  data() {
    return {
      loading: false,
      dashboard_name: "",
      dashboard_typee: "",
      subscription_id: "",
      feed_typee: "",
      screatkey: "",
      idaccount: "",
      clientid: "",
      clientscret: "",
      accesskey: "",
      tenant_id: "",
      awscostobject: {},
      azureobject: {},
      description: "",
      dashboard_type: "",
      Password: "",
      Dashboard_item: [{
        name: "Dashboard",
        value: "DASHBOARD"
      }, {
        name: "Feed",
        value: "FEED"
      }],
      feed_item: [{
        name: "AWS Cost",
        value: "AWS_COST"
      }, {
        name: "Azure Cost",
        value: "AZURE_COST"
      }],
      types_item: ["OPEN", "RESTRICTED"],
      name_rule: [v => !!v || "Required"
      // (v) => v.length <= 25 || "Max 25 characters",
      // (v) => v.trim().length != 0 || "Name Cannot be empty",
      ],
      description_rule: [v => !!v || "Required"
      // (v) => v.length <= 100 || "Max 100 characters",
      // (v) => v.trim().length != 0 || "Description Cannot be empty",
      ]
    };
  },
  methods: {
    close_dialog() {
      this.$refs.form.reset();
      this.$refs.form.resetValidation();
      this.$emit("clicked", 0);
    },
    create_dashboard() {
      if (this.$refs.form.validate()) {
        this.awscostobject = {
          account_id: this.idaccount,
          accesskey: this.accesskey,
          secretkey: this.screatkey
        };
        this.azureobject = {
          client_id: this.clientid,
          client_secrect: this.clientscret,
          subscription_id: this.subscription_id,
          tenant_id: this.tenant_id
        };
        this.Createdash_board();
      }
    },
    async Createdash_board() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(createDashboard, {
          input: {
            dashboard_name: this.dashboard_name,
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            dashboard_description: this.description,
            dashboard_security: this.dashboard_type,
            dashboard_password: this.dashboard_type == "RESTRICTED" ? this.Password : "NONE",
            dashboard_publish_type: this.dashboard_typee,
            dashboard_feed_type: this.dashboard_typee == "FEED" ? this.feed_typee : undefined,
            dashboard_account_details: this.dashboard_typee == "FEED" ? this.feed_typee == "AWS_COST" ? JSON.stringify(this.awscostobject) : JSON.stringify(this.azureobject) : undefined
          }
        }));
        var response = JSON.parse(result.data.createDashboard);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        // console.log(error);
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
